=== AuditPoolAdded.java
package net.officefloor.hq.app.pool;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Records the pool added. Runs after every rule has passed, so a refused change writes nothing. */
public class AuditPoolAdded {
    public void audit(@Val Pool pool, HttpServletRequest request, Audit audit) {
        audit.record("POOL_ADDED sheet=" + pool.sheetId() + " by=" + Audit.user(request) + " name=" + pool.name());
    }
}
=== AuditPoolMemberAdded.java
package net.officefloor.hq.app.pool;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Records the member added. Runs after every rule has passed, so a refused change writes nothing. */
public class AuditPoolMemberAdded {
    public void audit(@Val PoolMember member, HttpServletRequest request, Audit audit) {
        audit.record("POOL_MEMBER_ADDED sheet=" + member.sheetId() + " by=" + Audit.user(request)
                + " pool=" + member.pool() + " name=" + member.name() + " share=" + member.share().toPlainString());
    }
}
=== HandleInvalidPool.java
package net.officefloor.hq.app.pool;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidPool {
    public void handle(@Parameter InvalidPoolException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
